import {
  CaseTypeConfigSchema,
  type CaseTypeConfig,
  type Field,
  type FieldType,
  type LayoutRow,
  type Phase,
  type PhaseRule,
  type Role,
  type RuleTrigger,
} from '../schema'

/**
 * Converts CANEA ONE configuration exports — the workflow and rule import scripts generated by
 * conf-import-tool (export_workflow.sql / export_rules.sql) — into a CaseTypeConfig.
 *
 * CANEA ONE keeps fields per phase and links them across phases with a metadata category, so a
 * category becomes one Nexus field placed in every phase it appears in. Registry values come from
 * a registry export (id, name, path); people in that export are deliberately not imported —
 * person fields pick from the Nexus users.
 *
 * Pure: give it the file contents, get the config and a report of what could not be translated.
 */

export interface RegistryNode {
  id: number
  name: string
  /** Dot-separated ids from the root, e.g. "1.6.4568.4569" */
  path: string
  active: boolean
}

export interface ImportReport {
  translated: string[]
  approximated: string[]
  skipped: string[]
}

export interface ImportResult {
  config: CaseTypeConfig
  report: ImportReport
}

// ---------------------------------------------------------------------------
// SQL value tokenizer
// ---------------------------------------------------------------------------

type SqlValue = null | number | string | { map: string; id: number } | { raw: string }

/** Splits a SQL value list on top-level commas, skipping -- comments and respecting quotes and parentheses. */
function splitValues(src: string): string[] {
  const out: string[] = []
  let cur = ''
  let depth = 0
  for (let i = 0; i < src.length; i++) {
    const ch = src[i]
    if (ch === "'") {
      let j = i + 1
      while (j < src.length) {
        if (src[j] === "'" && src[j + 1] === "'") j += 2
        else if (src[j] === "'") break
        else j++
      }
      cur += src.slice(i, j + 1)
      i = j
    } else if (ch === '-' && src[i + 1] === '-') {
      while (i < src.length && src[i] !== '\n') i++
    } else if (ch === '(') {
      depth++
      cur += ch
    } else if (ch === ')') {
      depth--
      cur += ch
    } else if (ch === ',' && depth === 0) {
      out.push(cur.trim())
      cur = ''
    } else cur += ch
  }
  if (cur.trim()) out.push(cur.trim())
  return out
}

function parseValue(v: string): SqlValue {
  if (/^NULL$/i.test(v)) return null
  if (/^-?\d+(\.\d+)?$/.test(v)) return Number(v)
  const str = v.match(/^N?'([\s\S]*)'$/)
  if (str) return str[1].replace(/''/g, "'")
  const map = v.match(/^\(SELECT (?:TOP 1 )?NewID FROM @(\w+) WHERE OldID = (\d+)\)$/)
  if (map) return { map: map[1], id: Number(map[2]) }
  return { raw: v }
}

const unq = (s: string) => s.replace(/''/g, "'")
const str = (v: SqlValue) => (typeof v === 'string' ? v : '')
const num = (v: SqlValue) => (typeof v === 'number' ? v : 0)
const ref = (v: SqlValue, map: string) => (v && typeof v === 'object' && 'map' in v && v.map === map ? v.id : null)

// ---------------------------------------------------------------------------
// Workflow script
// ---------------------------------------------------------------------------

interface Item {
  id: number
  phaseId: number
  name: string
  render: string
  values: Record<string, SqlValue>
  panelId: number | null
  referenceItemId: number | null
  pos?: { y: number; x: number; span: number }
}

interface ParsedWorkflow {
  name: string
  prefix: string
  phases: { id: number; name: string; internalName: string; order: number; casePhaseId: number }[]
  roleTypes: Map<number, string>
  roleItems: Map<number, number>
  permissions: { roleItemId: number; casePhaseId: number; edit: boolean; end: boolean; forward: boolean; backward: boolean }[]
  categories: Map<number, string>
  registryRoots: Map<number, string>
  items: Item[]
}

function parseWorkflow(sql: string): ParsedWorkflow {
  const s = sql.replace(/\r\n/g, '\n')
  const name = s.match(/^-- Source: (.+?) \(ID: \d+\)/m)?.[1]?.trim() ?? 'Imported case type'
  const prefix = s.match(/INSERT INTO ImproofCaseTypes \([\s\S]*?\)\nVALUES \(\n\s*'(?:[^']|'')*',\n\s*'((?:[^']|'')*)'/)?.[1] ?? ''

  const phaseDefs = [...s.matchAll(/DECLARE @NewPhaseID_(\d+) INT\nINSERT INTO ImproofPhaseTypes \(Name, InternalName\)\nVALUES \('((?:[^']|'')*)', '((?:[^']|'')*)'\)/g)].map((m) => ({
    id: Number(m[1]),
    name: unq(m[2]),
    internalName: unq(m[3]),
  }))
  const order = new Map<number, number>()
  const casePhase = new Map<number, number>()
  for (const m of s.matchAll(/SELECT @NewCaseTypeID, NewID, (\d+), [^\n]*\nFROM @PhaseMap WHERE OldID = (\d+)\n[\s\S]*?INSERT INTO @CasePhaseMap VALUES \((\d+), @NewCasePhaseID_\d+, (\d+)\)/g)) {
    order.set(Number(m[2]), Number(m[1]))
    casePhase.set(Number(m[4]), Number(m[3]))
  }
  const phases = phaseDefs
    .map((p) => ({ ...p, order: order.get(p.id) ?? 99, casePhaseId: casePhase.get(p.id) ?? 0 }))
    .sort((a, b) => a.order - b.order)

  const roleTypes = new Map([...s.matchAll(/INSERT @RoleMap VALUES \((\d+), N'((?:[^']|'')*)',/g)].map((m) => [Number(m[1]), unq(m[2])]))
  const roleItems = new Map([...s.matchAll(/INSERT INTO @RoleItemMap VALUES \((\d+), @NewRoleItemID_\d+, (\d+)\)/g)].map((m) => [Number(m[1]), Number(m[2])]))
  const permissions = [...s.matchAll(/SELECT ri\.NewID, cp\.NewID, (\d), (\d), (\d), (\d)\nFROM @RoleItemMap ri, @CasePhaseMap cp\nWHERE ri\.OldID = (\d+) AND cp\.OldID = (\d+)/g)].map((m) => ({
    edit: m[1] === '1',
    end: m[2] === '1',
    forward: m[3] === '1',
    backward: m[4] === '1',
    roleItemId: Number(m[5]),
    casePhaseId: Number(m[6]),
  }))
  const categories = new Map([...s.matchAll(/INSERT @CategoryMap VALUES \((\d+), N'((?:[^']|'')*)',/g)].map((m) => [Number(m[1]), unq(m[2])]))
  const registryRoots = new Map([...s.matchAll(/INSERT @RegistryMap VALUES \((\d+), '((?:[^']|'')*)',/g)].map((m) => [Number(m[1]), unq(m[2]).trim()]))

  const items: Item[] = []
  for (const block of s.split(/\n-- Field: /).slice(1)) {
    const id = Number(block.match(/DECLARE @NewItemID_(\d+) INT/)?.[1])
    const insert = block.match(/INSERT INTO ImproofPhaseItemTypes \(([\s\S]*?)\)\nSELECT\n([\s\S]*?)\nFROM @PhaseMap pm WHERE pm\.OldID = (\d+)/)
    if (!id || !insert) continue
    const cols = insert[1].split(',').map((c) => c.trim())
    const vals = splitValues(insert[2]).map(parseValue)
    const values = Object.fromEntries(cols.map((c, i) => [c, vals[i] ?? null]))
    const meta = s.match(new RegExp(`INSERT INTO @ItemMap VALUES \\(${id}, @NewItemID_${id}, '(\\w+)', (NULL|\\d+)\\)`))
    items.push({
      id,
      phaseId: Number(insert[3]),
      name: str(values.InfoText).trim(),
      render: meta?.[1] ?? str(values.RenderAs),
      values,
      panelId: meta && meta[2] !== 'NULL' ? Number(meta[2]) : ref(values.CollapsiblePanelID, 'ItemMap'),
      referenceItemId: null,
    })
  }
  const byId = new Map(items.map((i) => [i.id, i]))
  for (const m of s.matchAll(/SET ReferenceItemID = \(SELECT NewID FROM @ItemMap WHERE OldID = (\d+)\)\nWHERE _phaseItemTypeID = @NewItemID_(\d+)/g)) {
    const child = byId.get(Number(m[2]))
    if (child) child.referenceItemId = Number(m[1])
  }
  for (const m of s.matchAll(/SELECT (\d+), (\d+), (\d+), im\.NewID FROM @ItemMap im WHERE im\.OldID = (\d+)/g)) {
    const it = byId.get(Number(m[4]))
    if (it) it.pos = { y: Number(m[1]), x: Number(m[2]), span: Number(m[3]) }
  }
  return { name, prefix, phases, roleTypes, roleItems, permissions, categories, registryRoots, items }
}

// ---------------------------------------------------------------------------
// Rules script
// ---------------------------------------------------------------------------

interface ParsedRule {
  name: string
  type: string
  phaseInternalName: string
  flags: { forward: boolean; back: boolean; end: boolean; save: boolean; button: boolean }
  evalAfterSave: boolean
  value1: string
  conditions: { itemId: number; constraint: number; registryItemId: number | null; value: string | null }[]
  ids: Record<number, number[]>
}

function parseRules(sql: string): ParsedRule[] {
  const s = sql.replace(/\r\n/g, '\n')
  return s
    .split(/\n-- Regel: /)
    .slice(1)
    .flatMap((block): ParsedRule[] => {
      const insert = block.match(/INSERT INTO ImproofRules \(([\s\S]*?)\)\nSELECT\n([\s\S]*?)\nSET @NewRuleID_/)
      if (!insert) return []
      const cols = insert[1].split(',').map((c) => c.trim())
      const vals = splitValues(insert[2]).map(parseValue)
      const v = Object.fromEntries(cols.map((c, i) => [c, vals[i] ?? null]))
      const conditions = [...block.matchAll(/INSERT INTO ImproofRuleConditions[\s\S]*?VALUES \(\n\s*@NewRuleID_\d+,\n\s*@CondField_\d+_(\d+),\n\s*(\d+),\n\s*([^\n]*?),?\n\s*([^\n]*?),?\n\s*(\d+)\n\)/g)].map((m) => ({
        itemId: Number(m[1]),
        constraint: Number(m[2]),
        value: m[3] === 'NULL' ? null : str(parseValue(m[3])),
        registryItemId: Number(m[4].match(/OldID = (\d+)/)?.[1]) || null,
      }))
      const ids: Record<number, number[]> = {}
      for (const m of block.matchAll(/VALUES \(@NewRuleID_\d+, @RIDVal_\d+_(\d+)_(\d+), \d+,/g)) (ids[Number(m[1])] ??= []).push(Number(m[2]))
      return [
        {
          name: str(v.Name),
          type: str(v.RuleType),
          phaseInternalName: block.match(/PT\.InternalName = N'((?:[^']|'')*)'/)?.[1]?.replace(/''/g, "'") ?? '',
          flags: { forward: num(v.ApplyOnForward) === 1, back: num(v.ApplyOnBack) === 1, end: num(v.ApplyOnEnd) === 1, save: num(v.ApplyOnSave) === 1, button: num(v.ApplyOnButtonEvent) === 1 },
          evalAfterSave: num(v.EvalAfterSave) === 1,
          value1: str(v.Value1),
          conditions,
          ids,
        },
      ]
    })
}

// ---------------------------------------------------------------------------
// Conversion
// ---------------------------------------------------------------------------

const RENDER_TYPES: Record<string, FieldType> = {
  TextBox: 'text',
  Date: 'date',
  Timestamp: 'date',
  UserChoice: 'registryDropdown',
  CheckBox: 'checkbox',
  StaticText: 'staticText',
  Divider: 'delimiter',
  CollapsiblePanel: 'collapsiblePanel',
  Button: 'button',
  AttachFiles: 'attachments',
  URL: 'url',
  SubCase: 'subcase',
  Number: 'number',
  Image: 'image',
}

const LAYOUT_RENDERS = new Set(['StaticText', 'Divider', 'CollapsiblePanel', 'Button', 'Image'])

function camel(name: string): string {
  const words = name.normalize('NFKD').replace(/[^\w\s]/g, ' ').trim().split(/\s+/).filter(Boolean)
  return words.length ? words.map((w, i) => (i ? w[0].toUpperCase() + w.slice(1).toLowerCase() : w.toLowerCase())).join('') : 'field'
}

function uniqueId(base: string, taken: Set<string>): string {
  let id = base
  for (let n = 2; taken.has(id); n++) id = `${base}${n}`
  taken.add(id)
  return id
}

export function convertCaneaExport(workflowSql: string, rulesSql: string | null, registry: RegistryNode[] | null): ImportResult {
  const wf = parseWorkflow(workflowSql)
  const report: ImportReport = { translated: [], approximated: [], skipped: [] }
  const nodes = new Map((registry ?? []).map((n) => [n.id, n]))
  const children = (id: number) =>
    (registry ?? []).filter((n) => n.active && n.path.split('.').slice(-2, -1)[0] === String(id)).map((n) => n)

  // Roles: CANEA role types on the case type; names containing "group" are inboxes
  const roleIdOf = new Map<number, string>()
  const takenRoleIds = new Set<string>()
  const roles: Role[] = [...new Set(wf.roleItems.values())].map((typeId) => {
    const name = wf.roleTypes.get(typeId) ?? `Role ${typeId}`
    const id = uniqueId(camel(name), takenRoleIds)
    roleIdOf.set(typeId, id)
    return { id, name, description: '', kind: /group/i.test(name) ? 'group' : 'user' }
  })
  const roleOfItem = (roleItemId: number) => roleIdOf.get(wf.roleItems.get(roleItemId) ?? -1)
  report.translated.push(`${roles.length} roles (${roles.filter((r) => r.kind === 'group').length} treated as group inboxes because the name says "group")`)

  // Fields: one per metadata category; items without a category are their own field
  const takenFieldIds = new Set<string>()
  const fieldIdOfItem = new Map<number, string>()
  const fields: Field[] = []
  const fieldByKey = new Map<string, Field>()
  const registries: CaseTypeConfig['registries'] = []
  const registryIdOfRoot = new Map<string, string>()
  const takenRegistryIds = new Set<string>()
  let usersRegistry = false

  /** Registry id → the registry nodes its values come from (a sub-choice takes the children of these). */
  const valueNodes = new Map<string, RegistryNode[]>()

  /**
   * A registry for a choice field. Top level: the children of its registry node. Sub-choice (the
   * field refers to a parent field): the children of the parent's values, each mapped to its parent
   * value — CANEA ONE's chained questions walk down one tree this way.
   */
  const registryFor = (rootId: number | null, fieldName: string, parent?: { registryId: string }): string | null => {
    const key = `${rootId ?? ''}<${parent?.registryId ?? ''}`
    const existing = registryIdOfRoot.get(key)
    if (existing) return existing
    let nodesForValues: RegistryNode[] = []
    const parents: Record<string, string> = {}
    const parentNodes = parent ? valueNodes.get(parent.registryId) ?? [] : []
    const ownRootUnderParent = rootId !== null && parentNodes.some((p) => p.id === rootId)
    if (parent && (rootId === null || !ownRootUnderParent) && parentNodes.length && (rootId === null || parentNodes.some((p) => nodes.get(rootId)?.path.startsWith(p.path.split('.').slice(0, -1).join('.'))))) {
      const shared = new Set<string>()
      for (const p of parentNodes) for (const c of children(p.id)) {
        nodesForValues.push(c)
        const v = c.name.trim()
        if (parents[v] && parents[v] !== p.name.trim()) shared.add(v)
        parents[v] = p.name.trim()
      }
      // One parent per value in the Nexus model: values under several parents are offered for all
      for (const v of shared) delete parents[v]
      if (shared.size) report.approximated.push(`"${fieldName}": ${[...shared].join(', ')} appear under several answers and are always offered`)
    }
    if (!nodesForValues.length && rootId !== null) {
      nodesForValues = children(rootId)
      const anc = nodes.get(rootId)?.path.split('.').map(Number) ?? []
      const parentValue = parentNodes.find((p) => anc.includes(p.id))
      if (parentValue) for (const n of nodesForValues) parents[n.name.trim()] = parentValue.name.trim()
    }
    if (rootId === null && !nodesForValues.length) return null
    const rootName =
      (rootId !== null ? nodes.get(rootId)?.name.trim() ?? wf.registryRoots.get(rootId) : null) ??
      'Registry'
    // A sub-choice list is named after its question; a top-level one after the registry node
    const listName = parent ? fieldName || rootName : rootName
    const id = uniqueId(`r-${camel(listName)}`, takenRegistryIds)
    registryIdOfRoot.set(key, id)
    valueNodes.set(id, nodesForValues)
    const values = [...new Set(nodesForValues.map((n) => n.name.trim()))]
    registries.push({ id, name: listName, values, comments: rootId ? `Imported from CANEA ONE registry node ${rootId}` : 'Sub-choice imported from CANEA ONE', parentRegistryId: parent?.registryId ?? null, parents })
    if (!registry) report.approximated.push(`Registry "${listName}" has no values — no registry export was given`)
    return id
  }

  const itemsById = new Map(wf.items.map((i) => [i.id, i]))
  const panelName = (it: Item) => (it.panelId ? itemsById.get(it.panelId)?.name ?? '' : '')

  for (const it of wf.items) {
    if (it.render === 'Divider' || it.render === 'CollapsiblePanel') continue
    const category = ref(it.values.MetadataCategoryID, 'CategoryMap')
    const layout = LAYOUT_RENDERS.has(it.render)
    const key = !layout && category ? `c${category}` : !layout && it.name ? `n${it.render}:${it.name}` : `i${it.id}`
    const existing = fieldByKey.get(key)
    if (existing) {
      fieldIdOfItem.set(it.id, existing.id)
      continue
    }
    let type: FieldType = RENDER_TYPES[it.render] ?? 'text'
    if (!RENDER_TYPES[it.render]) report.approximated.push(`Field type ${it.render} ("${it.name}") imported as text`)
    if (it.render === 'TextBox' && num(it.values.TextboxRows) > 1) type = 'textMultiline'
    const roleToSet = ref(it.values.RoleTypeIDToSet, 'RoleMap')
    const root = ref(it.values.UserChoiceReferenceRegistryID, 'RegistryMap')
    let registryId: string | null = null
    if (it.render === 'UserChoice') {
      const roleName = roleToSet ? wf.roleTypes.get(roleToSet) ?? '' : ''
      if (roleToSet && /group/i.test(roleName)) {
        // CANEA ONE sets a group role from the chosen org unit; Nexus binds group roles to groups up front
        registryId = root ? registryFor(root, it.name) : null
        report.approximated.push(`"${it.name}" sets the group role ${roleName} from the chosen value — bind that role to groups under Basics instead`)
      } else if (roleToSet) {
        type = 'registrySearch'
        registryId = 'r-users'
        usersRegistry = true
      } else {
        const parentItem = it.referenceItemId ? itemsById.get(it.referenceItemId) : undefined
        const parentField = parentItem ? fieldIdOfItem.get(parentItem.id) : undefined
        const parentRegistry = parentField ? fields.find((f) => f.id === parentField)?.registryId : null
        registryId = registryFor(root, it.name, parentRegistry ? { registryId: parentRegistry } : undefined)
        if (!registryId) report.approximated.push(`Choice field "${it.name}" has no registry in the export`)
      }
    }
    // Static texts keep their text in the default value (often HTML)
    const staticText = it.render === 'StaticText' ? str(it.values.DefaultValue).replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim() : ''
    if (it.render === 'StaticText' && !it.name) it.name = staticText.slice(0, 200) || 'Text'
    const name = (category ? wf.categories.get(category) : null) ?? (it.name || it.render)
    const field: Field = {
      id: uniqueId(camel(it.name || name), takenFieldIds),
      name: layout ? it.name || name : it.name || name,
      type,
      section: panelName(it),
      mandatory: false,
      registryId,
      multi: it.render === 'UserChoice' ? num(it.values.IsSingleChoice) === 0 : false,
      comments: category ? `CANEA ONE property category: ${wf.categories.get(category)}` : '',
      assignsRoleId: type === 'registrySearch' && roleToSet ? roleIdOf.get(roleToSet) ?? null : null,
    }
    fields.push(field)
    fieldByKey.set(key, field)
    fieldIdOfItem.set(it.id, field.id)
  }
  if (usersRegistry) registries.unshift({ id: 'r-users', name: 'Users', values: [], comments: 'The system users', parentRegistryId: null, parents: {} })
  report.translated.push(`${wf.items.length} phase items → ${fields.length} fields (items sharing a property category became one field; dividers and panels became layout rows)`)

  // Phases with placements, permissions and layout
  const phaseIdOf = new Map<number, string>()
  const takenPhaseIds = new Set<string>()
  const phaseByInternal = new Map<string, Phase>()
  const phases: Phase[] = wf.phases.map((p) => {
    const id = uniqueId(camel(p.name), takenPhaseIds)
    phaseIdOf.set(p.id, id)
    const permissions: Phase['permissions'] = {}
    for (const perm of wf.permissions.filter((x) => x.casePhaseId === p.casePhaseId)) {
      const roleId = roleOfItem(perm.roleItemId)
      if (roleId && (perm.edit || perm.end || perm.forward || perm.backward))
        permissions[roleId] = { edit: perm.edit, forward: perm.forward, backward: perm.backward, preEnd: perm.end }
    }
    const fieldsInPhase: Phase['fields'] = {}
    const its = wf.items.filter((i) => i.phaseId === p.id)
    for (const it of its) {
      const fid = fieldIdOfItem.get(it.id)
      if (!fid || num(it.values.IsHidden) === 1 || fieldsInPhase[fid]) continue
      const field = fields.find((f) => f.id === fid)!
      const title = it.name && it.name !== field.name ? it.name : null
      fieldsInPhase[fid] = { access: num(it.values.IsReadOnly) === 1 ? 'readOnly' : 'edit', mandatory: null, title }
    }
    const responsible = Object.entries(permissions).filter(([, v]) => v.forward).map(([k]) => k)
    const phase: Phase = {
      id,
      name: p.name,
      description: '',
      responsibleRoleIds: responsible.length ? responsible : Object.entries(permissions).filter(([, v]) => v.preEnd).map(([k]) => k),
      permissions,
      fields: fieldsInPhase,
      layout: buildLayout(its, fieldIdOfItem, fieldsInPhase),
      rules: [],
      deadlineDays: null,
      deadlineHours: null,
    }
    phaseByInternal.set(p.internalName, phase)
    return phase
  })
  report.translated.push(`${phases.length} phases with role × phase permissions and form layout`)

  // Rules
  const rules = rulesSql ? parseRules(rulesSql) : []
  if (!rulesSql) report.skipped.push('No rule export given — mandatory fields and conditions are missing')
  const registryName = (id: number | null) => (id ? nodes.get(id)?.name.trim() ?? null : null)
  let ruleCount = 0

  for (const r of rules) {
    const phase = phaseByInternal.get(r.phaseInternalName)
    if (!phase) {
      report.skipped.push(`Rule "${r.name}": phase ${r.phaseInternalName} not found`)
      continue
    }
    const triggers: RuleTrigger[] = [
      ...(r.flags.forward ? (['onForward'] as const) : []),
      ...(r.flags.back ? (['onBackward'] as const) : []),
      ...(r.flags.end ? (['onPreEnd'] as const) : []),
      ...(r.flags.save ? (['onSave'] as const) : []),
      ...(r.flags.button ? (['onButtonClick'] as const) : []),
    ]
    const targets = [...new Set((r.ids[1] ?? r.ids[2] ?? []).map((id) => fieldIdOfItem.get(id)).filter((x): x is string => !!x))]
    const cond = r.conditions[0]
    let when: PhaseRule['when'] = null
    let condition = ''
    if (cond) {
      const fieldId = fieldIdOfItem.get(cond.itemId)
      const value = registryName(cond.registryItemId) ?? cond.value
      if (!fieldId) condition = `Condition on a field that was not imported (${cond.itemId})`
      else if (value === null) when = { fieldId, operator: cond.constraint === 4 ? 'notEmpty' : 'empty', value: '' }
      else if (cond.constraint === 0 || cond.constraint === 4) when = { fieldId, operator: cond.constraint === 0 ? 'eq' : 'neq', value }
      else condition = `Unsupported CANEA ONE condition type ${cond.constraint}`
      if (r.conditions.length > 1) report.approximated.push(`Rule "${r.name}": only the first of ${r.conditions.length} conditions was imported`)
      if (condition) report.approximated.push(`Rule "${r.name}": ${condition}`)
    }
    const base = { id: `rule-${++ruleCount}`, name: r.name, triggers, when, condition, comments: `CANEA ONE ${r.type}` }

    if (r.type === 'CheckValueRule') {
      const editable = targets.filter((t) => phase.fields[t]?.access === 'edit')
      if (!when && !condition) {
        // Unconditional mandatory check → mandatory placements in the phase
        for (const t of editable) phase.fields[t].mandatory = true
        report.translated.push(`"${r.name}" (${phase.name}): ${editable.length} mandatory fields`)
      } else if (editable.length === 0 && when && (r.flags.end !== r.flags.forward)) {
        // A check that can never pass (targets not editable) is CANEA's way to forbid a move
        phase.rules.push({ ...base, type: 'direction', allowed: r.flags.end ? 'forward' : 'preEnd', message: r.name, triggers: [r.flags.end ? 'onPreEnd' : 'onForward'] })
        report.approximated.push(`"${r.name}" (${phase.name}): a check on non-editable fields — imported as a forced direction`)
      } else {
        phase.rules.push({ ...base, type: 'mandatory', fieldIds: editable.length ? editable : targets })
        report.translated.push(`"${r.name}" (${phase.name}): conditional mandatory fields`)
      }
    } else if (r.type === 'ProtectedFieldRule') {
      const appliesTo = (r.ids[7] ?? []).map(roleOfItem)
      const all = (r.ids[6] ?? []).map(roleOfItem)
      const exempt = all.filter((x) => !appliesTo.includes(x)).filter((x): x is string => !!x)
      if (r.value1 === 'False' && !exempt.length) {
        phase.rules.push({ ...base, type: 'fieldAccess', fieldIds: targets, access: 'hidden', triggers: ['afterSave'] })
        report.translated.push(`"${r.name}" (${phase.name}): hidden fields${when ? ' with condition' : ''}`)
      } else {
        const names = exempt.map((id) => roles.find((x) => x.id === id)?.name).join(', ')
        const othersCanEdit = Object.entries(phase.permissions).some(([rid, p]) => p.edit && !exempt.includes(rid) && roles.find((x) => x.id === rid)?.kind !== 'group')
        if (exempt.length && !othersCanEdit) {
          report.approximated.push(`"${r.name}" (${phase.name}): read-only for everyone except ${names} — Nexus already limits group roles to the assignment field`)
        } else {
          phase.rules.push({ ...base, type: 'fieldAccess', fieldIds: targets, access: r.value1 === 'False' ? 'hidden' : 'readOnly', when: null, condition: exempt.length ? `For everyone except ${names}` : condition, triggers: ['afterSave'] })
          report.approximated.push(`"${r.name}" (${phase.name}): role-specific field protection kept as a note (not evaluated)`)
        }
      }
    } else if (r.type === 'SigningRule') {
      phase.rules.push({ ...base, type: 'eSignature' })
      report.translated.push(`"${r.name}" (${phase.name}): e-signature ${triggers.join(', ')}`)
    } else if (r.type === 'SaveRule') {
      phase.rules.push({ ...base, type: 'saveCheckIn' })
      report.translated.push(`"${r.name}" (${phase.name}): save/check-in on button`)
    } else {
      report.skipped.push(`"${r.name}" (${phase.name}): rule type ${r.type} is not supported yet`)
    }
  }

  const config = CaseTypeConfigSchema.parse({
    caseTypeName: wf.name,
    prefix: wf.prefix,
    description: `Imported from a CANEA ONE export of "${wf.name}".`,
    roles,
    registries,
    fields,
    phases,
    notes: 'Imported from CANEA ONE. See the import report for what was approximated or skipped.',
  })
  return { config, report }
}

/** Layout from CANEA ONE form cells (3-column grid, rows by Y); panels become headed sections. */
function buildLayout(items: Item[], fieldIdOf: Map<number, string>, placed: Phase['fields']): LayoutRow[] {
  const rows: LayoutRow[] = []
  const used = new Set<string>()
  let n = 0
  const rowId = () => `lr-imp-${n++}`

  const emit = (group: Item[]) => {
    const sorted = [...group].sort((a, b) => (a.pos?.y ?? 999) - (b.pos?.y ?? 999) || (a.pos?.x ?? 0) - (b.pos?.x ?? 0))
    let currentY: number | null = null
    let cells: { fieldId: string; span: number }[] = []
    const flush = () => {
      if (cells.length) rows.push({ id: rowId(), type: 'fields', cells })
      cells = []
    }
    for (const it of sorted) {
      if (it.render === 'CollapsiblePanel') {
        flush()
        rows.push({ id: rowId(), type: 'header', title: it.name })
        emit(items.filter((c) => c.panelId === it.id))
        currentY = null
        continue
      }
      if (it.render === 'Divider') {
        flush()
        if (rows.length && rows[rows.length - 1].type !== 'divider') rows.push({ id: rowId(), type: 'divider' })
        continue
      }
      const fid = fieldIdOf.get(it.id)
      if (!fid || !placed[fid] || used.has(fid)) continue
      used.add(fid)
      const y = it.pos?.y ?? null
      const span = Math.max(1, Math.min(3, it.pos?.span ?? 1))
      const width = cells.reduce((s, c) => s + c.span, 0)
      if (y !== currentY || width + span > 3) flush()
      currentY = y
      cells.push({ fieldId: fid, span })
    }
    flush()
  }

  emit(items.filter((i) => !i.panelId))
  return rows
}
